import { test, expect } from '@playwright/test';
import path from 'path';
import { stamp, uniquePhone, ANON_HINT } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

type Lang = 'en' | 'ru' | 'ar';
const L: Record<Lang, { dialog: string; first: RegExp; last: RegExp; phone: RegExp; field: RegExp; next: RegExp; dir: 'ltr' | 'rtl' }> = {
  en: { dialog: 'Add candidate', first: /^First name/, last: /^Last name/, phone: /^Phone/, field: /expertise/i, next: /^(Continue|Next)$/, dir: 'ltr' },
  ru: { dialog: 'Добавить кандидата', first: /^Имя/, last: /^Фамилия/, phone: /^Телефон/, field: /экспертиз|специализац/i, next: /^(Продолжить|Далее)$/, dir: 'ltr' },
  ar: { dialog: 'إضافة مرشح', first: /^الاسم الأول/, last: /^اسم العائلة/, phone: /الهاتف/, field: /تخصص|الخبرة/, next: /^(متابعة|التالي|استمرار)$/, dir: 'rtl' },
};

test.describe('Anonymous candidate: AI title and summary without identifying details (#d4f6e7)', () => {
  for (const lang of ['en', 'ru', 'ar'] as Lang[]) {
    test(`«הוספת מועמד» step 2: identifying-details hint under the title in ${lang} @desktop #d4f6e7`, async ({ page }) => {
      test.setTimeout(120_000);
      const l = L[lang];
      await page.goto(`/${lang}/my-candidates/new`);
      await expect(page.locator('html')).toHaveAttribute('lang', lang);
      await expect(page.locator('html')).toHaveAttribute('dir', l.dir);
      const dialog = page.getByRole('dialog', { name: l.dialog });

      // Step 1 — required fields only
      await dialog.getByRole('textbox', { name: l.first }).fill('QA-AUTO-d4f6e7');
      await dialog.getByRole('textbox', { name: l.last }).fill(`${lang.toUpperCase()}${stamp()}`);
      await dialog.getByRole('textbox', { name: l.phone }).first().fill(uniquePhone());
      await dialog.getByRole('button', { name: l.field }).first().click();
      await page.getByRole('option').first().click();
      await page.keyboard.press('Escape');
      await dialog.getByRole('button', { name: l.next }).click();

      // Step 2 — title is generated, the hint is in this language (מה רצוי p.2 «Texts in he/en/ru/ar»)
      await expect(page.locator('#c-ai-title')).toHaveValue(/\S/, { timeout: 60_000 });
      await expect(dialog.getByText(ANON_HINT[lang])).toBeVisible();
      await expect(dialog.getByText(ANON_HINT.he)).toHaveCount(0);

      // Leave without «סיום» — nothing is saved
      await page.goto(`/${lang}/my-candidates`);
    });
  }
});
